 63	    private static final class LegacyGraphAdapter {
 64	        private static final int DESTINATION_INDEX = 0;
 65	        private static final int WEIGHT_INDEX = 1;
 66	        private static final int EDGE_FIELD_COUNT = 2;
 67	
 68	        private LegacyGraphAdapter() {
 69	        }
 70	
 71	        private static void addUndirectedEdge(ArrayList<ArrayList<int[]>> adj, int u, int v, int weight) {
 72	            validateAdjacencyList(adj);
 73	            validateVertex(u, adj.size(), "u");
 74	            validateVertex(v, adj.size(), "v");
 75	            validateWeight(weight);
 76	
 77	            adj.get(u).add(edge(v, weight));
 78	            adj.get(v).add(edge(u, weight));
 79	        }
