 81	        private static Graph toGraph(ArrayList<ArrayList<int[]>> adj) {
 82	            validateAdjacencyList(adj);
 83	
 84	            int vertexCount = adj.size();
 85	            Graph graph = Graph.withVertexCount(vertexCount);
 86	            for (int vertex = 0; vertex < vertexCount; vertex++) {
 87	                ArrayList<int[]> rawEdges = adj.get(vertex);
 88	                if (rawEdges == null) {
 89	                    throw new IllegalArgumentException(
 90	                            "Adjacency list contains a null neighbor list at vertex " + vertex);
 91	                }
 92	
 93	                for (int[] rawEdge : rawEdges) {
 94	                    validateRawEdge(rawEdge, vertex);
 95	                    int neighbor = rawEdge[DESTINATION_INDEX];
 96	                    int weight = rawEdge[WEIGHT_INDEX];
 97	
 98	                    validateVertex(neighbor, vertexCount, "neighbor");
 99	                    validateWeight(weight);
100	                    graph.addDirectedEdge(vertex, neighbor, weight);
101	                }
102	            }
103	            return graph;
104	        }
