121	    private static final class ShortestPathSolver {
122	        private final Graph graph;
123	        private final int[] distances;
124	        private final PriorityQueue<QueueEntry> minHeap;
125	
126	        private ShortestPathSolver(Graph graph, int source) {
127	            this.graph = graph;
128	            this.distances = createDistances(graph.vertexCount(), source);
129	            this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
130	            minHeap.offer(new QueueEntry(0, source));
131	        }
132	
133	        private static int[] solve(Graph graph, int source) {
134	            return new ShortestPathSolver(graph, source).run();
135	        }
136	
137	        private int[] run() {
138	            while (!minHeap.isEmpty()) {
139	                QueueEntry current = minHeap.poll();
140	                if (isStale(current)) {
141	                    continue;
142	                }
143	
144	                relaxNeighborsOf(current);
145	            }
146	            return distances;
147	        }
148	
149	        private boolean isStale(QueueEntry entry) {
150	            return entry.distance != distances[entry.vertex];
151	        }
152	
153	        private void relaxNeighborsOf(QueueEntry current) {
154	            for (Edge edge : graph.neighborsOf(current.vertex)) {
155	                tryRelax(current, edge);
156	            }
157	        }
158	
159	        private void tryRelax(QueueEntry current, Edge edge) {
160	            int nextDistance = addDistances(current.distance, edge.weight);
161	            if (nextDistance < distances[edge.to]) {
162	                distances[edge.to] = nextDistance;
163	                minHeap.offer(new QueueEntry(nextDistance, edge.to));
164	            }
165	        }
166	
167	        private static int[] createDistances(int vertexCount, int source) {
168	            int[] distances = new int[vertexCount];
169	            Arrays.fill(distances, UNREACHABLE);
170	            distances[source] = 0;
171	            return distances;
172	        }
173	    }
