191	    private static ArrayList<Integer> toArrayList(int[] distances) {
192	        ArrayList<Integer> result = new ArrayList<>(distances.length);
193	        for (int distance : distances) {
194	            result.add(distance);
195	        }
196	        return result;
197	    }
