200	        Graph graph = Graph.withVertexCount(5);
201	        graph.addUndirectedEdge(0, 1, 4);
202	        graph.addUndirectedEdge(0, 2, 8);
203	        graph.addUndirectedEdge(1, 4, 6);
204	        graph.addUndirectedEdge(1, 2, 3);
205	        graph.addUndirectedEdge(2, 3, 2);
206	        graph.addUndirectedEdge(3, 4, 10);
207	        return graph;
208	    }
