211	        StringBuilder formatted = new StringBuilder();
212	        for (int index = 0; index < distances.size(); index++) {
213	            if (index > 0) {
214	                formatted.append(' ');
215	            }
216	            formatted.append(distances.get(index));
217	        }
218	        return formatted.toString();
219	    }
