221	    private static int addDistances(int left, int right) {
222	        long sum = (long) left + right;
223	        if (sum > Integer.MAX_VALUE) {
224	            throw new ArithmeticException("Shortest path exceeds supported integer range");
225	        }
226	        return (int) sum;
227	    }
