263	    private static void validateRawEdge(int[] rawEdge, int fromVertex) {
264	        if (rawEdge == null || rawEdge.length < LegacyGraphAdapter.EDGE_FIELD_COUNT) {
265	            throw new IllegalArgumentException(
266	                    "Edge at vertex " + fromVertex + " must contain destination and weight");
267	        }
268	    }
